/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_Trans">_Trans</param>
void initFromCustInvoiceTrans(AVACBSCustProjInvoiceTrans _Trans)
{
    next initFromCustInvoiceTrans(_trans);
    if (_Trans.TableId == tableNum(CustInvoiceTrans))
    {
        CustInvoiceTrans            locCustInvoiceTrans = CustInvoiceTrans::findInventTransid(_Trans.InventTransId);
        this.CustAccount = locCustInvoiceTrans.custInvoiceJour().OrderAccount;
        this.InventSiteId = locCustInvoiceTrans.inventDim().InventSiteId;
    }
}
